-- =====================================================================
-- V10 — Inward entry variants.
-- The Inward (GRN) flow seeded in V8 had a single entry page
-- (pico:grn-create). Real customers want to CHOOSE the entry source:
--   1. From SAP (auto-pull via M11 outbound connector)
--   2. Manual (existing pico:grn-create, kept as-is)
--   3. From an existing Purchase Order (PO lookup → prefill items)
--   4. From the list of open POs (one-click receive from a filtered list)
-- =====================================================================

-- 1. Chooser page — branch to one of the 4 source-specific pages -----------
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:inward-chooser','New Inward','Choose how to start an inward receipt.','M5','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:inward-chooser');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"How are you receiving these items?","fields":[{"kind":"WorkflowActionButton","label":"From SAP (auto-pull)","action":"page.open","args":{"pageCode":"pico:grn-from-sap"},"variant":"primary"},{"kind":"WorkflowActionButton","label":"Manual entry","action":"page.open","args":{"pageCode":"pico:grn-create"}},{"kind":"WorkflowActionButton","label":"From an existing PO #","action":"page.open","args":{"pageCode":"pico:grn-from-po"}},{"kind":"WorkflowActionButton","label":"Pick from open POs list","action":"page.open","args":{"pageCode":"pico:grn-from-po-list"}}]}]}', 'V10', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:inward-chooser' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

-- 2. From-SAP page — uses M11 outbound to pull items
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:grn-from-sap','Inward from SAP','Pull GRN draft from SAP via M11 outbound.','M5','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:grn-from-sap');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Pull from SAP","fields":[{"kind":"FormField","type":"text","name":"sapDocNo","label":"SAP Document # (e.g. 5100001234)"},{"kind":"FormField","type":"text","name":"sapPlant","label":"SAP Plant (e.g. PICO-CBE)"},{"kind":"WorkflowActionButton","label":"Pull from SAP","action":"external.api.call","args":{"connector":"OUTBOUND_REST","operation":"GET /sap/grn/{sapDocNo}","autoMap":true},"variant":"primary"},{"kind":"FormField","type":"text","name":"pulledItemsPreview","label":"Pulled Items (preview, read-only)","readOnly":true},{"kind":"WorkflowActionButton","label":"Create GRN from SAP data","action":"workflow.transition","args":{"workflowCode":"M5.InwardReceipt","source":"SAP"},"variant":"primary"}]}]}', 'V10', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:grn-from-sap' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

-- 3. From-PO page — single PO lookup, prefill items
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:grn-from-po','Inward from PO','Look up a PO and prefill GRN.','M5','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:grn-from-po');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"From existing Purchase Order","fields":[{"kind":"FormField","type":"text","name":"poNumber","label":"PO #","placeholder":"PO-2026-001"},{"kind":"WorkflowActionButton","label":"Lookup PO","action":"page.refresh","variant":"secondary"},{"kind":"FormField","type":"text","name":"poVendor","label":"Vendor (from PO)","readOnly":true},{"kind":"FormField","type":"text","name":"poItems","label":"Items (from PO)","readOnly":true},{"kind":"FormField","type":"number","name":"qtyReceived","label":"Qty Received"},{"kind":"FormField","type":"text","name":"lotNo","label":"Lot #"},{"kind":"WorkflowActionButton","label":"Create GRN from PO","action":"workflow.transition","args":{"workflowCode":"M5.InwardReceipt","source":"PO"},"variant":"primary"}]}]}', 'V10', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:grn-from-po' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

-- 4. From-PO-list page — filtered list of SENT_TO_VENDOR POs, inline Receive
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:grn-from-po-list','Open POs','Pick a PO to receive against.','M5','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:grn-from-po-list');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"list","schemaVersion":2,"dataSource":{"type":"entity","entity":"PurchaseOrder","filter":{"and":[{"field":"tenant_id","op":"eq","value":1},{"field":"status","op":"in","value":["SENT_TO_VENDOR","APPROVED"]}]},"select":["id","po_number","vendor_name","total_value","required_by_date","status"]},"columns":[{"field":"po_number","label":"PO #","sticky":"left","sortable":true},{"field":"vendor_name","label":"Vendor"},{"field":"total_value","label":"Value","render":"number","align":"right"},{"field":"required_by_date","label":"Required By","render":"date"},{"field":"status","label":"Status","render":"badge","colorMap":{"APPROVED":"blue","SENT_TO_VENDOR":"amber"}}],"rowActions":[{"label":"Receive","action":"page.open","args":{"pageCode":"pico:grn-from-po","passField":"poNumber","fromColumn":"po_number"}}],"filters":[{"field":"_q","label":"Search","type":"text-contains","applyTo":["po_number","vendor_name"]}],"sort":{"default":[{"field":"required_by_date","dir":"asc"}]},"pagination":{"kind":"server","pageSize":25},"header":{"title":"Open Purchase Orders","actions":[{"label":"Manual GRN","action":"page.open","args":{"pageCode":"pico:grn-create"}}]},"responsive":{"mobile":{"renderAs":"cards","cardFields":["po_number","vendor_name","total_value","status"]}}}', 'V10', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:grn-from-po-list' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:inward-chooser','pico:grn-from-sap','pico:grn-from-po','pico:grn-from-po-list') AND current_version_id IS NULL;
